const fetchWeatherData = async (city) => {
  const apiUrl = `https://api.openweathermap.org/data/2.5/weather?q=${city}&units=metric&appid=YOUR_API_KEY`;
  let attempts = 0;
  const maxAttempts = 3;
  const initialDelay = 1000; // 1 second initial delay

  const fetchData = async () => {
    try {
      const response = await fetch(apiUrl);
      if (!response.ok) {
        throw new Error(`HTTP error! status: ${response.status}`);
      }
      const jsonData = await response.json();
      return jsonData;
    } catch (error) {
      attempts++;
      if (attempts < maxAttempts) {
        const delay = initialDelay * Math.pow(2, attempts) + Math.random() * 1000; // Exponential backoff with jitter
        console.warn(`Attempt ${attempts}/${maxAttempts} failed. Retrying in ${delay / 1000} seconds...`);
        await new Promise((resolve) => setTimeout(resolve, delay));
        return fetchData();
      } else {
        throw error;
      }
    }
  };

  try {
    const weatherData = await fetchData();
    return weatherData;
  } catch (error) {
    console.error('Failed to fetch weather data:', error);
    // Notify user after 3 failed attempts
    notifyUser('Failed to fetch weather data. Please try again later.');
  }
